def compute_order_amount(on_hand_inventory, pipeline_orders):
    base_stock = 702.9060205001728  # OPT_PARAM: {"initial": 702.9060205001728, "min": 500, "max": 900, "type": "float"}
    smoothing_factor = 0.23948320365755157  # OPT_PARAM: {"initial": 0.23948320365755157, "min": 0.0, "max": 1.0, "type": "float"}
    pipeline_coverage = 0.5746473958237776  # OPT_PARAM: {"initial": 0.5746473958237776, "min": 0.5, "max": 1.0, "type": "float"}

    pipeline_sum = sum(pipeline_orders)
    adjusted_pipeline = pipeline_sum * pipeline_coverage
    net_inventory = on_hand_inventory + adjusted_pipeline
    order_amount = max(0, base_stock - net_inventory) * smoothing_factor
    return order_amount
